  'tip.locBr': { en: `Local tax (brackets)`, nl: `Lokale belasting (schijven)`, fr: `Impôt local (tranches)` },
  'tip.vatM': {
    en: `US sales tax is added at the till, and most states exempt groceries, rent and many services, so this is an upper bound. The rate is the state rate plus the population-weighted average of local rates.`,
    nl: `De Amerikaanse sales tax komt bij de kassa bovenop de prijs, en de meeste staten stellen voeding, huur en veel diensten vrij, dus dit is een bovengrens. Het tarief is dat van de staat plus het gewogen gemiddelde van de lokale tarieven.`,
    fr: `La taxe de vente américaine s'ajoute en caisse et la plupart des États exonèrent l'alimentation, les loyers et beaucoup de services : c'est donc un maximum. Le taux est celui de l'État plus la moyenne pondérée des taux locaux.`,
  },
